/**
 * One meaningful moment in the reading history.
 */
sealed class ActivityKind {
    
    object Added : ActivityKind()
    
    
    object Started : ActivityKind()
    
    
    /**
     * Pages read in one sitting. Updates within an hour of each other are
     * merged into one entry.
     */
    data class Progress(
        val `fromPage`: kotlin.UInt, 
        val `toPage`: kotlin.UInt) : ActivityKind()
        
    {
        

        companion object
    }
    
    object Finished : ActivityKind()
    
    
    /**
     * Moved back to Want to Read or Reading from another status.
     */
    data class StatusChanged(
        val `status`: uniffi.pocket_library_core.ReadingStatus) : ActivityKind()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeActivityKind : FfiConverterRustBuffer<ActivityKind>{
    override fun read(buf: ByteBuffer): ActivityKind {
        return when(buf.getInt()) {
            1 -> ActivityKind.Added
            2 -> ActivityKind.Started
            3 -> ActivityKind.Progress(
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                )
            4 -> ActivityKind.Finished
            5 -> ActivityKind.StatusChanged(
                FfiConverterTypeReadingStatus.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ActivityKind): ULong = when(value) {
        is ActivityKind.Added -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is ActivityKind.Started -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is ActivityKind.Progress -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`fromPage`)
                + FfiConverterUInt.allocationSize(value.`toPage`)
            )
        }
        is ActivityKind.Finished -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is ActivityKind.StatusChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeReadingStatus.allocationSize(value.`status`)
            )
        }
    }

    override fun write(value: ActivityKind, buf: ByteBuffer) {
        when(value) {
            is ActivityKind.Added -> {
                buf.putInt(1)
                Unit
            }
            is ActivityKind.Started -> {
                buf.putInt(2)
                Unit
            }
            is ActivityKind.Progress -> {
                buf.putInt(3)
                FfiConverterUInt.write(value.`fromPage`, buf)
                FfiConverterUInt.write(value.`toPage`, buf)
                Unit
            }
            is ActivityKind.Finished -> {
                buf.putInt(4)
                Unit
            }
            is ActivityKind.StatusChanged -> {
                buf.putInt(5)
                FfiConverterTypeReadingStatus.write(value.`status`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





